ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS cleaning_selected_size text, ADD COLUMN IF NOT EXISTS cleaning_selected_range text, ADD COLUMN IF NOT EXISTS cleaning_bathrooms numeric, ADD COLUMN IF NOT EXISTS cleaning_measured_sqft integer, ADD COLUMN IF NOT EXISTS cleaning_verified_size text, ADD COLUMN IF NOT EXISTS cleaning_verified_bathrooms numeric, ADD COLUMN IF NOT EXISTS cleaning_verified_at timestamptz, ADD COLUMN IF NOT EXISTS cleaning_verified_by uuid, ADD COLUMN IF NOT EXISTS cleaning_size_confirmation text, ADD COLUMN IF NOT EXISTS cleaning_team_ready boolean NOT NULL DEFAULT false;
ALTER TABLE public.stripe_catalog ADD COLUMN IF NOT EXISTS cleaning_size smallint, ADD COLUMN IF NOT EXISTS billing_period text NOT NULL DEFAULT 'monthly';
COMMENT ON COLUMN public.stripe_catalog.cleaning_size IS 'Cleaning-specific five-band size; legacy size remains three-tier for compatibility.';
CREATE OR REPLACE FUNCTION public.cleaning_size_from_sqft(_sqft integer, _baths numeric) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE n integer; cap numeric; BEGIN IF _sqft IS NULL OR _sqft <= 0 OR _baths IS NULL OR _baths < 0 THEN RETURN NULL; END IF; n := CASE WHEN _sqft <= 1400 THEN 1 WHEN _sqft <= 2200 THEN 2 WHEN _sqft <= 3200 THEN 3 WHEN _sqft <= 4800 THEN 4 WHEN _sqft <= 7000 THEN 5 ELSE 6 END; IF n=6 THEN RETURN 'custom'; END IF; cap := (ARRAY[2,2.5,3.5,5,6.5]::numeric[])[n]; IF _baths > cap THEN n := n+1; END IF; RETURN CASE WHEN n=6 THEN 'custom' ELSE n::text END; END $$;
GRANT EXECUTE ON FUNCTION public.cleaning_size_from_sqft(integer,numeric) TO anon,authenticated,service_role;